import{_ as t,c as o,o as i,ae as n}from"./chunks/framework.BIhw3mML.js";const r="/oe-user-docs/assets/app-centre-doc-en.DkEpykl4.png",s="/oe-user-docs/assets/doc-filter-en.z8fJlI_C.png",a="/oe-user-docs/assets/doc-detail-en.CXYP8XZC.png",l="/oe-user-docs/assets/doc-info-en.DqZndL-P.png",c="/oe-user-docs/assets/doc-confirm-en.ByUFYeJU.png",d="/oe-user-docs/assets/doc-tbd-en.DApVfrmh.png",p="/oe-user-docs/assets/doc-add-en.Z9HSUaaV.png",u="/oe-user-docs/assets/doc-action-en.B8Z1ZGtY.png",P=JSON.parse('{"title":"Document AI Detection","description":"","frontmatter":{},"headers":[],"relativePath":"en/doc.md","filePath":"en/doc.md"}'),g={name:"en/doc.md"};function h(m,e,b,f,q,A){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="document-ai-detection" tabindex="-1">Document AI Detection <a class="header-anchor" href="#document-ai-detection" aria-label="Permalink to &quot;Document AI Detection&quot;">​</a></h1><p><strong>Version: 1.0</strong><br><strong>Release Date: January 01, 2026</strong><br><strong>Applicable to: Alert Recipients, Action Item Responsible Persons, Regional Quality/EHS Representatives, Compliance Committee Members</strong></p><h2 id="_1-role-description" tabindex="-1">1. Role Description <a class="header-anchor" href="#_1-role-description" aria-label="Permalink to &quot;1. Role Description&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Permission Scope</th><th>Entry Point</th></tr></thead><tbody><tr><td><strong>Alert/Action Item Recipient</strong></td><td>Only handle tasks assigned to themselves<br>• No access to 【Application Center】</td><td>Home → 【Pending Confirmation Alerts】<br>Home → 【Pending Action Items】</td></tr><tr><td><strong>Application Owner</strong><br>(Regional Quality/EHS Representative, Compliance Committee Member)</td><td>Can retrieve all alerts in their region<br>• Can export and analyze data</td><td>【AI Alerting Application Center】→ Sub-applications</td></tr></tbody></table><h2 id="_2-operation-guide" tabindex="-1">2. Operation Guide <a class="header-anchor" href="#_2-operation-guide" aria-label="Permalink to &quot;2. Operation Guide&quot;">​</a></h2><h3 id="_2-1-function-overview" tabindex="-1">2.1 Function Overview <a class="header-anchor" href="#_2-1-function-overview" aria-label="Permalink to &quot;2.1 Function Overview&quot;">​</a></h3><p>The system automatically retrieves document samples from business systems (such as inspection forms, major components, torque reports, etc.), and AI models will identify the following risks:</p><ul><li>Missing critical information (such as signatures, seals, missing dates, etc.)</li><li>Failed inspection conclusions</li></ul><h3 id="_2-2-applicable-business" tabindex="-1">2.2 Applicable Business <a class="header-anchor" href="#_2-2-applicable-business" aria-label="Permalink to &quot;2.2 Applicable Business&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Business Domain</th><th>Application Name</th></tr></thead><tbody><tr><td><strong>On-site Quality</strong></td><td>Document AI Detection</td></tr><tr><td><strong>On-site EHS</strong></td><td>EHS Risk AI Detection</td></tr></tbody></table><h3 id="_2-3-main-interface" tabindex="-1">2.3 Main Interface <a class="header-anchor" href="#_2-3-main-interface" aria-label="Permalink to &quot;2.3 Main Interface&quot;">​</a></h3><p>Access path: 【Alert Application Center】 → 【Document AI Detection Application】</p><p><img src="'+r+'" alt="Document Class Main List Page"></p><h3 id="_2-4-filtering-and-querying" tabindex="-1">2.4 Filtering and Querying <a class="header-anchor" href="#_2-4-filtering-and-querying" aria-label="Permalink to &quot;2.4 Filtering and Querying&quot;">​</a></h3><p>Supports filtering by the following conditions:</p><ul><li>Alert item number, time, status</li><li>AI monitoring model (such as torque report, fire protection/inspection)</li><li>Belonging region, work order number, project code, etc.</li></ul><p><img src="'+s+'" alt="Document Class Filter Area"></p><h3 id="_2-5-alert-details-and-review" tabindex="-1">2.5 Alert Details and Review <a class="header-anchor" href="#_2-5-alert-details-and-review" aria-label="Permalink to &quot;2.5 Alert Details and Review&quot;">​</a></h3><ul><li>Click the 【View】 button on the right to enter the detail page:</li></ul><p><img src="'+a+'" alt="Document Detail Page - Panoramic View"></p><ul><li>In the detail page: <ul><li>Display <strong>Document PDF</strong> centered, AI automatically highlights abnormal areas (such as red boxes marking &quot;No Signature&quot;)</li><li>Left side shows <strong>Alert List</strong>, listing specific problem points (such as &quot;No 1: Information Missing&quot;)</li><li>Right side displays <strong>Alert Information</strong> and <strong>Document Basic Data</strong> (file name, uploader, work order number, etc.)</li></ul></li></ul><p><img src="'+l+'" alt="Alert Details"></p><ul><li>In the 【Confirmation Information】 area: <ul><li>Select <strong>Whether Problem</strong> (Yes / No)</li><li>Fill in <strong>Confirmation Description</strong> (required)</li></ul></li></ul><p><img src="'+c+'" alt="Wait for Confirm"></p><blockquote><p>✅ When selecting &quot;Yes&quot;, click the <strong>【Process】</strong> button, the system will pop up the 【Alert Processing】 dialog box, providing the following three processing methods:</p></blockquote><h4 id="processing-method-1-pending-subsequent-processing" tabindex="-1">Processing Method 1: Pending subsequent processing <a class="header-anchor" href="#processing-method-1-pending-subsequent-processing" aria-label="Permalink to &quot;Processing Method 1: Pending subsequent processing&quot;">​</a></h4><ul><li><strong>Applicable Scenario</strong>: Problem has been identified, but immediate rectification is not required (such as resource coordination, waiting for approval, etc.)</li><li><strong>Operation Steps</strong>: <ul><li>Select <strong>&quot;Yes&quot;</strong> in the dialog box</li><li>Select <strong>&quot;Wait for Processing&quot;</strong> from the dropdown menu</li><li>Fill in supplementary notes (such as &quot;Wait until next week to sign uniformly&quot;)</li></ul></li></ul><p><img src="'+d+'" alt="Wait for Processing"></p><ul><li><strong>System Behavior</strong>: <ul><li>Alert status updates to <strong>&quot;Closed&quot;</strong></li><li>Does not generate action items</li><li>Remains in alert records for subsequent tracking</li></ul></li></ul><h4 id="processing-method-2-close-with-remark" tabindex="-1">Processing Method 2: Close with remark <a class="header-anchor" href="#processing-method-2-close-with-remark" aria-label="Permalink to &quot;Processing Method 2: Close with remark&quot;">​</a></h4><ul><li><strong>Applicable Scenario</strong>: Problem has been resolved, no further action required, or acceptable deviation</li><li><strong>Operation Steps</strong>: <ul><li>Select <strong>&quot;Yes&quot;</strong></li><li>Select <strong>&quot;Close with Additional Information&quot;</strong> from the dropdown menu</li><li>Fill in supplementary notes</li><li>Can upload attachments as evidence</li></ul></li><li><strong>System Behavior</strong>: <ul><li>Alert status changes to <strong>&quot;Closed&quot;</strong></li><li>Does not create action items</li><li>Counted in &quot;Valid Alerts - Closed Loop&quot; statistics, used for quality analysis</li></ul></li></ul><p><img src="'+p+'" alt="Close with Additional Information Dialog"></p><h4 id="processing-method-3-add-actions" tabindex="-1">Processing Method 3: Add actions <a class="header-anchor" href="#processing-method-3-add-actions" aria-label="Permalink to &quot;Processing Method 3: Add actions&quot;">​</a></h4><ul><li><strong>Applicable Scenario</strong>: Need to specify responsible person, corrective measures and completion deadline (such as re-signing, data correction, process training, etc.)</li><li><strong>Operation Steps</strong>: <ul><li>Select <strong>&quot;Yes&quot;</strong></li><li>Select <strong>&quot;Add Action Item&quot;</strong> from the dropdown menu</li><li>Fill in measures, responsible person, expected completion time</li><li>Can upload attachments (such as communication records, standard templates)</li></ul></li><li><strong>System Behavior</strong>: <ul><li>Automatically generates a <strong>【Pending Closed Loop Action Item】</strong></li><li>Automatically assigns to current user (or can specify other responsible persons)</li><li>Pushes notification to responsible person&#39;s homepage</li><li>Action item status tracked independently, supports uploading rectification evidence and audit closure</li></ul></li></ul><p><img src="'+u+'" alt="Add Action Item Dialog"></p><blockquote><p>📌 <strong>Notes</strong>:</p><ul><li>&quot;Attachments&quot; support multiple file uploads (JPG, PNG, PDF, DOCX, etc.), single file ≤20MB</li><li>All submitted content (including processing method, description, attachments) are permanently recorded, supporting audit tracing</li><li>Once submitted, processing method cannot be changed; if adjustment needed, please contact application owner to initiate modification process</li></ul></blockquote><hr><h3 id="example-scenarios" tabindex="-1">Example Scenarios <a class="header-anchor" href="#example-scenarios" aria-label="Permalink to &quot;Example Scenarios&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Actual Scenario</th><th>Recommended Processing Method</th><th>Description</th></tr></thead><tbody><tr><td>AI misjudges handwritten signature as &quot;missing signature&quot;, actually signed</td><td>Close with Additional Information</td><td>Upload explanation, close quickly</td></tr><tr><td>Inspection form missing equipment number, needs supplementation</td><td>Add Action Item</td><td>Create action item task, assign operator</td></tr><tr><td>Accident report pending legal review before archiving</td><td>Wait for Processing</td><td>Explain review process, defer processing</td></tr></tbody></table><blockquote><p>🔍 <strong>General Notes</strong>:<br> The above three processing methods apply to <strong>Image, Document, APQP</strong> all alert types, ensuring flexible, compliant, and traceable problem response paths.</p></blockquote><h2 id="_3-operation-path-reference-table" tabindex="-1">3. Operation Path Reference Table <a class="header-anchor" href="#_3-operation-path-reference-table" aria-label="Permalink to &quot;3. Operation Path Reference Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Alert/Action Item Recipient</th><th>Application Owner</th></tr></thead><tbody><tr><td>Review Alert</td><td>Home →【Pending Confirmation Alerts】</td><td>Application Center → Sub-application → View Alert Items</td></tr><tr><td>Close Action Item</td><td>Home →【Pending Closed Loop Action Items】</td><td>Application Center → Sub-application → View Action Items</td></tr><tr><td>Export Data</td><td>❌ Not Supported</td><td>✅ Supported (Excel, CSV)</td></tr><tr><td>Global Search</td><td>❌ Not Supported</td><td>✅ Filter by region/project, etc.</td></tr></tbody></table><h2 id="_4-frequently-asked-questions-faq" tabindex="-1">4. Frequently Asked Questions (FAQ) <a class="header-anchor" href="#_4-frequently-asked-questions-faq" aria-label="Permalink to &quot;4. Frequently Asked Questions (FAQ)&quot;">​</a></h2><p><strong>Q: Why can&#39;t I see a certain alert on my homepage?</strong><br> A: The alert is not assigned to you. Please confirm whether the belonging work order/project is within your responsibility scope.</p><p><strong>Q: Can application owner review on behalf of recipient?</strong><br> A: Not recommended. The system follows the principle of &quot;who receives, who reviews&quot; to ensure accountability.</p><p><strong>Q: How to request application center permissions?</strong><br> A: Contact system administrator, provide role proof.</p><blockquote><p>🔍 <strong>More Questions</strong>: See the <a href="/oe-user-docs/en/faq.html">FAQ document</a></p></blockquote>',47)])])}const _=t(g,[["render",h]]);export{P as __pageData,_ as default};
